input.command:
node --experimental-sqlite -e "
const { DatabaseSync } = require('node:sqlite');
const db = new DatabaseSync('/bench/home/work/.codegraph/codegraph.db', {readOnly: true});
const entities = ['Attachment','IdentityProvider','Inbox','InstanceSetting','Memo','MemoRelation','MemoShare','Reaction','User','UserIdentity','UserSetting'];
for (const name of entities) {
  const target = db.prepare(\"select id from nodes where kind='struct' and file_path=? and name=?\").get(
    name==='Attachment' ? 'store/attachment.go' :
    name==='IdentityProvider' ? 'store/idp.go' :
    name==='Inbox' ? 'store/inbox.go' :
    name==='InstanceSetting' ? 'store/instance_setting.go' :
    name==='Memo' ? 'store/memo.go' :
    name==='MemoRelation' ? 'store/memo_relation.go' :
    name==='MemoShare' ? 'store/memo_share.go' :
    name==='Reaction' ? 'store/reaction.go' :
    name==='User' ? 'store/user.go' :
    name==='UserIdentity' ? 'store/user_identity.go' :
    'store/user_setting.go', name);
  if (!target) { console.log(name, 'NOT FOUND'); continue; }
  const rows = db.prepare(\`
    select n.file_path from edges e join nodes n on n.id = e.source
    where e.target = ? and n.file_path not like 'store/%'
  \`).all(target.id);
  const pkgs = new Set(rows.map(r => r.file_path.split('/').slice(0,-1).join('/')));
  console.log(name, '-> distinct files:', new Set(rows.map(r=>r.file_path)).size, 'distinct pkg-dirs:', pkgs.size, [...pkgs].slice(0,15));
}
" 2>&1 | grep -v ExperimentalWarning | grep -v trace-warnings

node --experimental-sqlite -e "
const { DatabaseSync } = require('node:sqlite');
const db = new DatabaseSync('/bench/home/work/.codegraph/codegraph.db', {readOnly: true});
const target = db.prepare(\"select id from nodes where kind='struct' and file_path='store/user.go' and name='User'\").get();
const rows = db.prepare(\`
  select n.file_path, e.kind from edges e join nodes n on n.id = e.source
  where e.target = ? and n.file_path not like 'store/%'
  order by n.file_path
\`).all(target.id);
console.log(rows);
" 2>&1 | grep -v ExperimentalWarning | grep -v trace-warnings

